await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const boots = await browserjs(tabId, () => {
  // Let's find product links and titles
  const cards = Array.from(document.querySelectorAll('a[href*="/products/"]'));
  const unique = new Map();
  for (const a of cards) {
    const text = a.innerText.trim();
    if (text && !unique.has(a.href)) {
      unique.set(a.href, text);
    }
  }
  return Array.from(unique.entries()).map(([url, text]) => ({ url, text }));
});
